'use client';

import * as React from 'react';
import { cn } from '@/lib/utils';
import { Input, type InputProps } from '../input/Input';

export type DatePickerProps = Omit<InputProps, 'type' | 'value' | 'defaultValue'> & {
  /** ISO date string (YYYY-MM-DD) — controlled. */
  value?: string;
  /** ISO date string — initial value when uncontrolled. */
  defaultValue?: string;
  /** Fired with the ISO string ('' when cleared). */
  onValueChange?: (value: string) => void;
  /** Show a clear button once a date is selected. */
  clearable?: boolean;
  /** Accessible label for the clear button. Default 'Clear date'. */
  clearLabel?: string;
};

/**
 * Native date field with an ISO-string contract. Uses the platform picker
 * (mobile date wheels, keyboard editing, locale formatting) rather than a
 * custom calendar, so accessibility and input methods come for free.
 */
export const DatePicker = React.forwardRef<HTMLInputElement, DatePickerProps>(function DatePicker(
  { value, defaultValue, onValueChange, onChange, clearable = false, clearLabel = 'Clear date', className, ...props },
  ref
) {
  const [internal, setInternal] = React.useState(defaultValue ?? '');
  const current = value ?? internal;

  const commit = (next: string) => {
    if (value === undefined) setInternal(next);
    onValueChange?.(next);
  };

  return (
    <div className={cn('relative flex items-center', className)}>
      <Input
        ref={ref}
        type="date"
        value={current}
        onChange={(event) => {
          commit(event.target.value);
          onChange?.(event);
        }}
        className={clearable && current ? 'pr-9' : undefined}
        {...props}
      />
      {clearable && current && (
        <button
          type="button"
          onClick={() => commit('')}
          aria-label={clearLabel}
          className="absolute right-1.5 inline-flex h-6 w-6 items-center justify-center rounded text-muted-foreground hover:text-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
        >
          ✕
        </button>
      )}
    </div>
  );
});

{
  "id": "date-picker",
  "name": "DatePicker",
  "tier": "molecule",
  "description": "Native date field with an ISO-string contract, min/max passthrough and an optional clear button.",
  "designIntent": "A custom calendar is a large accessibility surface. The platform date picker already handles locale formatting, keyboard editing and mobile wheels, so DatePicker standardizes the ISO contract and a clear affordance instead of reimplementing a calendar.",
  "props": [
    {
      "name": "value",
      "type": "string",
      "required": false,
      "description": "ISO date (YYYY-MM-DD), controlled."
    },
    {
      "name": "defaultValue",
      "type": "string",
      "required": false,
      "description": "ISO date, initial value."
    },
    {
      "name": "onValueChange",
      "type": "(value: string) => void",
      "required": false,
      "description": "Fired with the ISO string; '' when cleared."
    },
    {
      "name": "clearable",
      "type": "boolean",
      "required": false,
      "defaultValue": "false",
      "description": "Shows a clear button once a value exists."
    },
    {
      "name": "clearLabel",
      "type": "string",
      "required": false,
      "defaultValue": "Clear date",
      "description": "Accessible label for the clear button."
    }
  ],
  "examples": [
    {
      "title": "ISO date field",
      "code": "<DatePicker\n  aria-label=\"Start date\"\n  value={start}\n  onValueChange={setStart}\n  clearable\n/>",
      "description": "Controlled ISO value with a clear button."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't store locale-formatted strings",
      "explanation": "The contract is YYYY-MM-DD; format for display at the edge.",
      "example": "// Avoid: '03/11/2026' in state\n// Prefer: '2026-11-03'"
    }
  ],
  "accessibility": [
    {
      "feature": "Platform input",
      "implementation": "Renders input[type=date] so OS pickers and keyboard editing apply",
      "userRequirements": "Always provide a label (FormField or aria-label)"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Labels",
      "guidelines": [
        "Name the date's meaning, not 'Date'"
      ],
      "goodExamples": [
        "Start date",
        "Due on"
      ],
      "badExamples": [
        "Date"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "FormField",
      "relationship": "Wrap for label/hint/error wiring",
      "example": "<FormField id=\"start\" label=\"Start date\"><DatePicker /></FormField>"
    }
  ],
  "relatedComponents": [
    "TimePicker",
    "FormField",
    "Input"
  ],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.8.0",
  "sourceDir": "date-picker",
  "exportName": "DatePicker"
}
